import struct

def decode(x):
    bits = int.from_bytes(struct.pack('>d', x), 'big')
    sign = bits >> 63
    stored = (bits >> 52) & 0x7FF
    fraction = (bits & (2**52 - 1)) / 2**52
    return (sign, stored - 1023, fraction)

def machine_epsilon():
    eps = 1.0
    while 1.0 + eps / 2 > 1.0:
        eps /= 2
    return eps
